:root{--bg:#07111e;--card:#0d1b30;--bd:#1f3358;--ac:#7c9eff;--tx:#eaf1ff;--dim:#c7d6ec;--faint:#9cb0cf;--sw:280px}
*{box-sizing:border-box}html,body{overflow-x:hidden}
body{margin:0;background:var(--bg);color:var(--tx);font:16px/1.85 "Noto Sans JP","Hiragino Kaku Gothic ProN","Yu Gothic","Noto Sans CJK JP",sans-serif}
#side{position:fixed;left:0;top:0;bottom:0;width:var(--sw);overflow-y:auto;background:#050d18;border-right:1px solid var(--bd);padding:18px 12px;z-index:20}
#side .brand{font-weight:800;color:var(--ac);font-size:13px;padding:0 8px 12px;border-bottom:1px solid var(--bd);margin-bottom:10px}
#side a{display:block;color:var(--dim);text-decoration:none;font-size:13px;line-height:1.5;padding:5px 8px;border-radius:6px;border-left:2px solid transparent}
#side a.nav-h3{padding-left:20px;font-size:12px;color:var(--faint)}
#side a:hover{background:#0d1b30}#side a.active{color:#fff;background:#16294a;border-left-color:var(--ac)}
#tgl{display:none;position:fixed;top:10px;left:10px;z-index:30;background:#16294a;color:#fff;border:1px solid var(--bd);border-radius:8px;padding:6px 12px;font-size:18px}
.main{margin-left:var(--sw);padding:32px 48px 80px}
.hero{position:relative;background:var(--card);border:1px solid var(--bd);border-radius:16px;padding:32px;margin-bottom:32px;overflow:hidden}
.hero::before{content:"";position:absolute;top:-80px;right:-80px;width:300px;height:300px;background:radial-gradient(circle,rgba(124,158,255,.25),transparent 70%)}
.badge{display:inline-block;border:1px solid var(--ac);color:var(--ac);border-radius:999px;padding:2px 14px;font-size:12px;font-weight:700}
.hero-title{font-size:28px;font-weight:800;color:#fff;margin:14px 0 18px;line-height:1.4}
.metas{display:flex;flex-wrap:wrap}.m{padding:0 20px;border-right:1px solid var(--bd)}.m:first-child{padding-left:0}.m:last-child{border-right:0}
.m span{display:block;font-size:11px;letter-spacing:.05em;color:var(--faint)}.m b{font-size:14.5px;font-weight:500;color:var(--dim)}
h2{font-size:24px;margin:56px 0 16px;padding-bottom:8px;border-bottom:2px solid var(--bd);color:#fff;scroll-margin-top:16px}
h3{font-size:19px;margin:36px 0 10px;color:var(--ac);scroll-margin-top:16px}h4{font-size:16px;margin:24px 0 6px;color:var(--dim)}
p,li{color:var(--dim)}strong{color:#fff}a{color:var(--ac);word-break:break-all}hr{border:0;border-top:1px solid var(--bd);margin:28px 0}
code:not(pre code){background:#16294a;border-radius:4px;padding:1px 6px;font:13.5px "JetBrains Mono",monospace;color:#cfe0ff;overflow-wrap:break-word}
blockquote{margin:16px 0;padding:10px 16px;border-left:3px solid var(--ac);background:var(--card);border-radius:0 8px 8px 0}blockquote p{margin:4px 0}
p.callout{background:#101f3a;border:1px solid var(--bd);border-left:4px solid var(--ac);border-radius:8px;padding:12px 16px;margin:16px 0}
.glossary{background:var(--card);border:1px dashed var(--bd);border-radius:10px;padding:10px 18px;margin:24px 0}.glossary p{margin:4px 0;color:#fff;font-weight:700}.glossary ul{margin:4px 0 8px;font-size:14.5px}
.table-scroll{overflow-x:auto;margin:16px 0;border:1px solid var(--bd);border-radius:10px}
table{border-collapse:collapse;width:100%;font-size:14.5px}th{background:#16294a;color:#fff;text-align:left}th,td{padding:9px 14px;border-bottom:1px solid var(--bd);vertical-align:top;min-width:90px}tr:last-child td{border-bottom:0}td{color:var(--dim)}
.mermaid-diagram{display:block;overflow-x:auto;background:var(--card);border:1px solid var(--bd);border-radius:12px;padding:16px;margin:16px 0}
.mermaid-diagram svg{display:block;margin-left:auto;margin-right:auto;max-width:none;flex-shrink:0}
.mermaid-diagram p{color:inherit;margin:0}.mermaid-diagram foreignObject{overflow:visible}.mermaid-diagram .nodeLabel,.mermaid-diagram .edgeLabel{color:#eaf1ff}
ul,ol{padding-left:1.4em}input[type=checkbox]{accent-color:var(--ac);margin-right:6px}ul:has(input[type=checkbox]){list-style:none;padding-left:0}
.page-footer{margin-top:56px;padding-top:16px;border-top:1px solid var(--bd);font-size:13px;color:var(--faint)}
@media(max-width:900px){#side{transform:translateX(-100%);transition:.2s}#side.open{transform:none}#tgl{display:block}.main{margin-left:0;padding:60px 16px 60px}.hero{padding:20px}.m{border-right:0;border-bottom:1px solid var(--bd);padding:8px 0;width:100%}}
